#include <iomanip>
#include <iostream>
#include <map>
#include <string>

struct Stats {
    long calls = 0;    // what an instrumenter counts: every call
    long us = 0;       // and its exact time, in microseconds
    long samples = 0;  // what a sampler counts: the calls it happened to catch
};

int main() {
    const long interval = 997;  // a sample every 997 microseconds, about 1000 a second
    std::map<std::string, Stats> stats;
    long now = 0;
    long next_sample = interval;
    long total_samples = 0;

    // Runs one call of `us` microseconds on the simulated clock.
    auto run = [&](const std::string& name, long us) {
        Stats& s = stats[name];
        ++s.calls;
        s.us += us;
        const long end = now + us;
        while (next_sample < end) {  // each sample that lands inside this call
            ++s.samples;
            ++total_samples;
            next_sample += interval;
        }
        now = end;
    };

    // A backtest over 10,000 ticks: three steps per tick, and an order every 250 ticks.
    for (int tick = 1; tick <= 10000; ++tick) {
        run("parse_tick", 2);
        run("update_book", 3);
        run("signal", 5);
        if (tick % 250 == 0) {
            run("send_order", 40);
        }
    }

    std::cout << std::fixed << std::setprecision(1);
    std::cout << total_samples << " samples over " << now << " us\n";
    std::cout << "function     calls   time  samples  share\n";
    for (const auto& [name, s] : stats) {
        std::cout << std::left << std::setw(12) << name << std::right << std::setw(6) << s.calls << std::setw(6)
                  << 100.0 * s.us / now << '%' << std::setw(9) << s.samples << std::setw(6)
                  << 100.0 * s.samples / total_samples << "%\n";
    }
    return 0;
}

