#include <algorithm>
#include <iomanip>
#include <iostream>
#include <map>
#include <set>
#include <sstream>
#include <string>
#include <utility>
#include <vector>

int main() {
    // The Mac's profile of the slow backtest, folded: each stack once, root first, with its samples.
    const std::vector<std::pair<std::string, long>> folded = {
        {"main;crossover_signal;window_mean", 1023},
        {"main;risk_ok;window_mean", 676},
        {"main;risk_ok", 1},
        {"crossover_signal", 6},  // a sample that lost its caller's frame
        {"risk_ok", 6},
        {"main", 4},
    };
    std::map<std::string, long> self, total;
    long samples = 0;
    for (const auto& [stack, count] : folded) {
        std::vector<std::string> frames;
        std::istringstream in(stack);
        std::string frame;
        while (std::getline(in, frame, ';')) {
            frames.push_back(frame);
        }
        self[frames.back()] += count;  // the function that was running
        const std::set<std::string> on_stack(frames.begin(), frames.end());  // recursion counts once
        for (const std::string& f : on_stack) {
            total[f] += count;  // every function waiting on the stack
        }
        samples += count;
    }
    std::vector<std::string> names;
    for (const auto& [name, count] : total) {
        names.push_back(name);
    }
    std::sort(names.begin(), names.end(), [&](const std::string& a, const std::string& b) {
        return total[a] != total[b] ? total[a] > total[b] : a < b;
    });
    std::cout << samples << " samples\n" << std::fixed << std::setprecision(1);
    for (const std::string& name : names) {
        std::cout << std::left << std::setw(17) << name << std::right << " total " << std::setw(4) << total[name]
                  << " (" << std::setw(4) << 100.0 * total[name] / samples << "%), self " << std::setw(4)
                  << self[name] << " (" << std::setw(4) << 100.0 * self[name] / samples << "%)\n";
    }
    return 0;
}

