// -O2
#include <cmath>
#include <cstdint>
#include <cstdlib>
#include <iostream>
#include <string>
#include <vector>

// Mean of the `window` prices before `end`, added up again on every call.
[[gnu::noinline]] double window_mean(const std::vector<int64_t>& prices, std::size_t end, std::size_t window) {
    int64_t sum = 0;
    for (std::size_t i = end - window; i < end; ++i) {
        sum += prices[i];
    }
    return static_cast<double>(sum) / window;
}

// +1 while the 100-tick mean is above the 1000-tick mean, else -1.
[[gnu::noinline]] int crossover_signal(const std::vector<int64_t>& prices, std::size_t end) {
    return window_mean(prices, end, 100) > window_mean(prices, end, 1000) ? 1 : -1;
}

// True when the last price is within 40 ticks of the 500-tick mean.
[[gnu::noinline]] bool risk_ok(const std::vector<int64_t>& prices, std::size_t end) {
    return std::abs(prices[end - 1] - window_mean(prices, end, 500)) < 40;
}

// The fix: a running sum. Called for each end in order, it adds one price and drops one.
struct RollingMean {
    std::size_t window;
    int64_t sum = 0;
    double update(const std::vector<int64_t>& prices, std::size_t end) {
        sum += prices[end - 1];
        if (end > window) {
            sum -= prices[end - 1 - window];
        }
        return static_cast<double>(sum) / window;
    }
};

struct Result {
    long flips = 0, orders = 0;  // signal changes, and the ones that passed the risk check
    int last = 0;
    void record(int signal, bool ok) {
        flips += signal != last;
        orders += signal != last && ok;
        last = signal;
    }
};

int main(int argc, char* argv[]) {
    const std::string version = argc > 1 ? argv[1] : "both";  // the sandbox passes none
    const std::size_t n = argc > 2 ? std::atol(argv[2]) : 200000;
    std::vector<int64_t> prices(n);
    uint32_t x = 7;  // the same prices on every run: steps of -3, -1, 1, or 3
    for (std::size_t i = 0; i < n; ++i) {
        x = x * 1664525u + 1013904223u;
        prices[i] = (i == 0 ? 19275 : prices[i - 1]) + static_cast<int64_t>(x >> 30) * 2 - 3;
    }
    if (version != "fast") {
        Result r;
        for (std::size_t end = 1000; end <= n; ++end) {
            r.record(crossover_signal(prices, end), risk_ok(prices, end));
        }
        std::cout << "slow: " << r.flips << " flips, " << r.orders << " orders\n";
    }
    if (version != "slow") {
        Result r;
        RollingMean fast{100}, slow{1000}, risk{500};
        for (std::size_t end = 1; end <= n; ++end) {
            const double f = fast.update(prices, end), s = slow.update(prices, end), m = risk.update(prices, end);
            if (end >= 1000) {
                r.record(f > s ? 1 : -1, std::abs(prices[end - 1] - m) < 40);
            }
        }
        std::cout << "fast: " << r.flips << " flips, " << r.orders << " orders\n";
    }
    return 0;
}

