// -O2
#include <chrono>
#include <cstdint>
#include <iostream>
#include <map>
#include <string>

struct Probe {
    long calls = 0;
    int64_t ns = 0;
};
std::map<std::string, Probe> probes;  // every probe, by name

// Times one scope: the clock starts in the constructor and stops in the destructor.
class ScopedTimer {
public:
    explicit ScopedTimer(Probe& probe) : probe_(probe), start_(std::chrono::steady_clock::now()) {}
    ~ScopedTimer() {
        const auto elapsed = std::chrono::steady_clock::now() - start_;
        probe_.ns += std::chrono::duration_cast<std::chrono::nanoseconds>(elapsed).count();
        ++probe_.calls;
    }

private:
    Probe& probe_;
    std::chrono::steady_clock::time_point start_;
};

int64_t best_bid = 0, orders_sent = 0;

void send_order(int64_t price) {
    static Probe& probe = probes["send_order"];  // looked up once, on the first call
    ScopedTimer timer(probe);
    orders_sent += price > 0;
}

void on_quote(int64_t bid) {
    static Probe& probe = probes["on_quote"];
    ScopedTimer timer(probe);
    {
        static Probe& book = probes["on_quote/book"];  // a probe for part of a function
        ScopedTimer t(book);
        best_bid = bid;
    }
    if (bid % 250 == 0) {
        send_order(bid);
    }
}

int main() {
    uint32_t x = 3;
    for (int i = 0; i < 100000; ++i) {
        x = x * 1664525u + 1013904223u;
        on_quote(19000 + (x >> 22));  // bids from 19000 to 20023
    }
    for (const auto& [name, p] : probes) {
        std::cout << name << ": " << p.calls << " calls\n";
        // std::cout << "  " << p.ns / p.calls << " ns per call\n";
    }
    std::cout << "orders sent " << orders_sent << '\n';
    return 0;
}

