#include <chrono>
#include <cstdint>
#include <iostream>
#include <map>
#include <string>

struct Probe {
    long calls = 0;
    int64_t ns = 0;
};
std::map<std::string, Probe> probes;  // every probe, by name

// Times one scope: the clock starts in the constructor and stops in the destructor.
class ScopedTimer {
public:
    explicit ScopedTimer(Probe& probe) : probe_(probe), start_(std::chrono::steady_clock::now()) {}
    ~ScopedTimer() {
        const auto elapsed = std::chrono::steady_clock::now() - start_;
        probe_.ns += std::chrono::duration_cast<std::chrono::nanoseconds>(elapsed).count();
        ++probe_.calls;
    }

private:
    Probe& probe_;
    std::chrono::steady_clock::time_point start_;
};

bool size_ok(int64_t qty) {
    static Probe& probe = probes["size_ok"];
    ScopedTimer timer(probe);
    return qty > 0 && qty <= 1000;
}

bool price_ok(int64_t price, int64_t last) {
    static Probe& probe = probes["price_ok"];
    ScopedTimer timer(probe);
    return price > last - 50 && price < last + 50;
}

// The pre-trade risk check: the size first, and the price band only for a good size.
bool check_order(int64_t qty, int64_t price, int64_t last) {
    static Probe& probe = probes["check_order"];
    ScopedTimer timer(probe);
    return size_ok(qty) && price_ok(price, last);
}

int main() {
    int64_t last = 0, qty = 0, price = 0;
    std::cin >> last;  // the last trade price, in ticks
    long accepted = 0, rejected = 0;
    while (std::cin >> qty >> price) {
        if (check_order(qty, price, last)) {
            ++accepted;
        } else {
            ++rejected;
        }
    }
    for (const auto& [name, p] : probes) {
        std::cout << name << ": " << p.calls << " calls\n";
    }
    std::cout << accepted << " accepted, " << rejected << " rejected\n";
    return 0;
}
